script:
const AMB = "#d9822b", RED = "#c62828", MUT = "#5d7880", TEAL = "#2a9d8f";
let E = {};
function seg(api, t, a, b) { return api.seg(t, a, b, "ease_in_out"); }
function moveArt(api, id, parent) { const a = api.$(id); parent.appendChild(a); return a; }
function tag(api, g, txt, x, y, color) { return R.text(api, g, txt, x, y, {anchor: "middle", size: 16, weight: 800, color, halo: false}); }
function tile(api, g) {
  api.el("rect", {x: 46, y: 182, width: 164, height: 200, rx: 20, fill: "#fff6ea", stroke: AMB, "stroke-width": 3, "stroke-dasharray": "9 7"}, g);
}

function setup(api) {
  const A = api.$("#art"), L = api.el("g", {id: "lab2"}, api.svg);
  // organ window
  const win = api.el("g", {"clip-path": "url(#win)"}, A);
  api.el("rect", {x: 322, y: 150, width: 268, height: 320, rx: 22, fill: "#fff"}, win);
  const og = api.el("g", {transform: "translate(322 470) scale(1.4) translate(-322 -470)"}, win); og.appendChild(api.$("#organ"));
  api.el("rect", {x: 322, y: 150, width: 268, height: 320, rx: 22, fill: "none", stroke: "#c9d6dc", "stroke-width": 3}, A);
  // source tile
  tile(api, A);
  tag(api, A, "CARCINOGEN", 128, 168, AMB);
  E.q = R.text(api, A, "?", 128, 308, {anchor: "middle", size: 92, weight: 800, color: AMB, halo: false});
  // dust pile (tile contents)
  E.pile = api.el("g", {opacity: 0}, A);
  const rnd = api.random(7);
  const pts = [];
  for (let i = 0; i < 70; i++) { const a = rnd() * Math.PI * 2, r = Math.sqrt(rnd()) * 1; pts.push([128 + Math.cos(a) * r * 62, 322 + 24 + Math.sin(a) * r * 30 + (1 - r) * -6, 4 + rnd() * 4.5]); }
  pts.sort((p, q) => p[1] - q[1]);
  pts.forEach(([x, y, r]) => api.el("circle", {cx: x.toFixed(1), cy: y.toFixed(1), r: r.toFixed(1), fill: "url(#metal)", stroke: "#56636e", "stroke-width": 0.8}, E.pile));
  E.cloud = api.el("g", {opacity: 0}, A);
  [[88, 252, 7], [118, 236, 9], [150, 256, 6], [172, 238, 8], [104, 270, 5], [136, 274, 7], [166, 276, 5], [96, 224, 5]].forEach(([x, y, r]) => api.el("circle", {cx: x, cy: y, r, fill: "url(#metal)", stroke: "#56636e", "stroke-width": 0.8}, E.cloud));
  // path of the dust into the nostril
  const P = api.el("path", {d: "M 214 300 C 262 300 290 348 362 352 S 404 344 430 330", fill: "none", stroke: "none"}, L);
  E.flow = R.flow(api, A, P, {n: 9, r: 5, color: "#9aa7b2", period: 1900});
  E.ar1 = R.arrowGrow(api, A, "M 216 300 C 250 300 280 346 326 350", AMB, 6);
  E.ar2 = R.arrowGrow(api, A, "M 216 300 C 250 300 280 346 326 350", RED, 6);
  // tumour
  E.tum = R.lump(api, A, 440, 326, "tumour");
  E.glow = R.glow(api, A, 440, 326, {r: 40, color: "#e53935"});
  // labels
  E.cNose = [R.chip(api, L, "Nasal cavity", 396, 182, MUT, {size: 18}), R.leader(api, L, 470, 196, 484, 262, MUT)];
  E.cInh = R.chip(api, L, "Inhaled dusts", 46, 414, AMB, {size: 18});
  E.cAns = R.chip(api, L, "Nickel dust", 46, 414, RED, {size: 20});
  E.cTum = [R.chip(api, L, "Cancer", 500, 446, RED, {size: 18}), R.leader(api, L, 506, 428, 456, 342, RED)];
}
function render(t, api) {
  // beat 1: setup
  api.set(E.q, {opacity: (1 - seg(api, t, 2300, 2800)).toFixed(3)});
  R.fade(api, E.cNose, t, 300, 800);
  // beat 2: dust inhaled
  api.set(E.cloud, {opacity: (seg(api, t, 2400, 3000)).toFixed(3)});
  api.set(E.pile, {opacity: seg(api, t, 2500, 3100).toFixed(3)});
  R.fade(api, E.cInh, t, 2700, 3200, 4650, 4950);
  const on = seg(api, t, 2700, 3200);
  E.flow.update(t, on);
  E.ar1.update(t, api.seg(t, 2500, 3500, "ease_in_out"));
  const f = seg(api, t, 3300, 4600);
  E.tum.update(t, f, 30, 24, 0.5 * seg(api, t, 4600, 5000));
  // beat 3: answer
  E.ar2.update(t, api.seg(t, 4700, 5400, "ease_in_out"));
  E.glow.update(t, 0.8 * seg(api, t, 4700, 5300));
  R.fade(api, E.cAns, t, 4900, 5400);
  R.fade(api, E.cTum, t, 5200, 5700);
}
